import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from common import PySet
P = PySet()
p = P.p

p("Count items", "E", "counting", "count_items", "items", "Return a dict mapping each item (string) to the number of times it appears.", ["Use `dict.get(key, 0) + 1`."],
  "def count_items(items):\n    counts = {}\n    for x in items:\n        counts[x] = counts.get(x, 0) + 1\n    return counts", "`get` with a default avoids KeyError.", [(['a', 'b', 'a'],), ([],)], [(['x'],), (['a', 'a', 'a'],), (['b', 'a', 'c', 'b'],)])
p("Invert a dict", "E", "dicts", "invert", "d", "Swap keys and values of a dict whose values are unique strings.", ["Dict comprehension with swapped pair."],
  "def invert(d):\n    return {v: k for k, v in d.items()}", "Values become keys.", [({'a': 'x', 'b': 'y'},), ({},)], [({'k': 'v'},), ({'one': 'un', 'two': 'deux', 'three': 'trois'},), ({'x': 'y'},)])
p("Merge two dicts", "E", "dicts", "merge_dicts", "a, b", "Return a new dict with all keys of `a` and `b`; on conflict the value from `b` wins.", ["`{**a, **b}`."],
  "def merge_dicts(a, b):\n    return {**a, **b}", "Later entries override earlier ones.", [({'a': 1}, {'b': 2}), ({'a': 1}, {'a': 9})], [({}, {}), ({'x': 1, 'y': 2}, {'y': 3}), ({}, {'k': 'v'})])
p("Sum values by key", "M", "dicts", "sum_by_key", "pairs", "Given a list of `[key, number]` pairs return a dict with the sum of numbers per key.", ["Accumulate with `get`."],
  "def sum_by_key(pairs):\n    totals = {}\n    for k, v in pairs:\n        totals[k] = totals.get(k, 0) + v\n    return totals", "Group-by-and-sum in a single pass.", [([['a', 1], ['b', 2], ['a', 3]],), ([],)], [([['x', 5]],), ([['a', -1], ['a', 1]],), ([['k', 0.5], ['k', 0.25]],)])
p("Most frequent word", "M", "counting", "most_frequent_word", "text", "Return the most frequent word in a non-empty text (case-insensitive, words separated by whitespace). On ties return the alphabetically smallest.", ["Count lowercase words, then choose by (-count, word)."],
  "def most_frequent_word(text):\n    counts = {}\n    for w in text.lower().split():\n        counts[w] = counts.get(w, 0) + 1\n    return min(counts, key=lambda w: (-counts[w], w))", "A composite key handles the tie-break.", [("the cat and the dog",), ("a b a b",)], [("Hello hello HELLO",), ("x",), ("b a",)])
p("Group by length", "M", "dicts", "group_by_length", "words", "Group words by their length: return a dict whose keys are the lengths as strings and values are lists of words in input order.", ["Use `str(len(w))` as the key."],
  "def group_by_length(words):\n    groups = {}\n    for w in words:\n        groups.setdefault(str(len(w)), []).append(w)\n    return groups", "JSON keys must be strings, hence `str(len(w))`.", [(['a', 'bb', 'c', 'dd'],), ([],)], [(['hello'],), (['ab', 'cd', 'ef'],), (['a', 'bcd', 'e', 'fgh'],)])
p("Group anagrams count sizes", "M", "dicts", "anagram_group_sizes", "words", "Group words that are anagrams of each other and return the sorted list of group sizes (largest first).", ["Key by sorted letters."],
  "def anagram_group_sizes(words):\n    groups = {}\n    for w in words:\n        groups[''.join(sorted(w))] = groups.get(''.join(sorted(w)), 0) + 1\n    return sorted(groups.values(), reverse=True)", "Sizes only, so counts are enough.", [(['eat', 'tea', 'tan', 'ate', 'nat', 'bat'],), ([],)], [(['a'],), (['ab', 'ba', 'ab', 'cd'],), (['x', 'y'],)])
p("Two sum indices", "M", "dicts", "two_sum", "nums, target", "Return the indices `[i, j]` (i < j) of the two numbers adding up to `target`; exactly one pair exists.", ["Store values seen so far in a dict."],
  "def two_sum(nums, target):\n    seen = {}\n    for j, x in enumerate(nums):\n        if target - x in seen:\n            return [seen[target - x], j]\n        seen[x] = j", "One pass with O(1) lookups.", [([2, 7, 11, 15], 9), ([3, 2, 4], 6)], [([3, 3], 6), ([-1, -2, -3, -4, -5], -8), ([0, 4, 3, 0], 0)])
p("Valid anagram counts", "E", "counting", "same_counts", "a, b", "Return `True` if two lists contain the same items with the same multiplicities (order ignored). Items are hashable.", ["Compare count dicts."],
  "def same_counts(a, b):\n    def count(xs):\n        d = {}\n        for x in xs:\n            d[x] = d.get(x, 0) + 1\n        return d\n    return count(a) == count(b)", "Dict equality ignores order.", [([1, 2, 2], [2, 1, 2]), ([1, 2], [1, 1])], [([], []), (['a'], ['a', 'a']), ([1, 2, 3], [3, 2, 1])])
p("Character frequency sorted", "M", "counting", "char_freq_sorted", "s", "Return a list of `[char, count]` pairs sorted by count descending, then by character ascending.", ["Count, then sort with a tuple key."],
  "def char_freq_sorted(s):\n    counts = {}\n    for c in s:\n        counts[c] = counts.get(c, 0) + 1\n    return [[c, n] for c, n in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))]", "Negating the count sorts it descending.", [("hello",), ("",)], [("aabb",), ("zzyx",), ("mississippi",)])
p("Words starting with letter", "E", "dicts", "words_by_initial", "words", "Return a dict from each initial letter (lowercase) to the sorted list of words starting with it (case-insensitive grouping, original spelling kept).", ["Group by `w[0].lower()`, sort each group."],
  "def words_by_initial(words):\n    groups = {}\n    for w in words:\n        groups.setdefault(w[0].lower(), []).append(w)\n    return {k: sorted(v) for k, v in groups.items()}", "Group first, sort later.", [(['apple', 'avocado', 'banana'],), ([],)], [(['Cat', 'car'],), (['x'],), (['b', 'a', 'B'],)])
p("Inventory update", "M", "dicts", "apply_updates", "stock, updates", "Apply a list of `[item, delta]` updates to the `stock` dict (missing items start at 0). Remove items whose quantity becomes 0 or less. Return the new dict and do not mutate the input.", ["Copy first, then update."],
  "def apply_updates(stock, updates):\n    new = dict(stock)\n    for item, delta in updates:\n        new[item] = new.get(item, 0) + delta\n    return {k: v for k, v in new.items() if v > 0}", "Filtering at the end handles every item once.", [({'a': 2}, [['a', 1], ['b', 3]]), ({'a': 1}, [['a', -1]])], [({}, []), ({'x': 5}, [['x', -9]]), ({'p': 1, 'q': 2}, [['q', -1], ['p', 4]])])
p("Nested dict lookup", "M", "dicts", "deep_get", "d, path, default", "Look up a value in nested dicts following the list of keys `path`. If any key is missing, or an intermediate value is not a dict, return `default`.", ["Walk down one key at a time."],
  "def deep_get(d, path, default):\n    cur = d\n    for key in path:\n        if not isinstance(cur, dict) or key not in cur:\n            return default\n        cur = cur[key]\n    return cur", "Check type and membership at every level.", [({'a': {'b': 1}}, ['a', 'b'], None), ({'a': 1}, ['a', 'b'], 'x')], [({}, [], 0), ({'a': {'b': {'c': 5}}}, ['a', 'b'], None), ({'a': {}}, ['a', 'z'], -1)])
p("Flatten nested dict", "H", "dicts", "flatten_dict", "d", "Flatten nested dicts into one dict with dot-joined keys: `{'a': {'b': 1}}` -> `{'a.b': 1}`. Non-dict values are kept; empty nested dicts disappear.", ["Recurse with a prefix."],
  "def flatten_dict(d):\n    out = {}\n    def walk(cur, prefix):\n        for k, v in cur.items():\n            key = prefix + '.' + k if prefix else k\n            if isinstance(v, dict):\n                walk(v, key)\n            else:\n                out[key] = v\n    walk(d, '')\n    return out", "A helper closure writes into one output dict.", [({'a': {'b': 1, 'c': 2}, 'd': 3},), ({},)], [({'x': {'y': {'z': 0}}},), ({'a': {}},), ({'k': [1, 2], 'm': {'n': None}},)])
p("Unflatten dict", "H", "dicts", "unflatten_dict", "d", "Reverse of flattening: turn `{'a.b': 1, 'c': 2}` into `{'a': {'b': 1}, 'c': 2}`.", ["Split keys on `.` and create nested dicts as you go."],
  "def unflatten_dict(d):\n    out = {}\n    for key, value in d.items():\n        parts = key.split('.')\n        cur = out\n        for part in parts[:-1]:\n            cur = cur.setdefault(part, {})\n        cur[parts[-1]] = value\n    return out", "`setdefault` creates intermediate levels.", [({'a.b': 1, 'c': 2},), ({},)], [({'x.y.z': 0},), ({'a.b': 1, 'a.c': 2},), ({'k': None},)])
p("Dictionary from two lists", "E", "dicts", "make_dict", "keys, values", "Build a dict pairing `keys[i]` with `values[i]`; extra items in the longer list are ignored.", ["`dict(zip(...))`."],
  "def make_dict(keys, values):\n    return dict(zip(keys, values))", "`zip` truncates to the shorter input.", [(['a', 'b'], [1, 2]), (['a'], [1, 2])], [([], []), (['a', 'b', 'c'], [1]), (['k', 'k'], [1, 2])])
p("Sort dict by value", "E", "sorting", "sort_by_value", "d", "Return the keys of `d` ordered by their values ascending; ties by key ascending.", ["Sort with key `(d[k], k)`."],
  "def sort_by_value(d):\n    return sorted(d, key=lambda k: (d[k], k))", "A tuple key breaks ties.", [({'a': 3, 'b': 1, 'c': 2},), ({},)], [({'x': 1, 'y': 1},), ({'b': 0, 'a': 0, 'c': -1},), ({'z': 5},)])
p("Common keys", "E", "dicts", "common_keys", "a, b", "Return the sorted list of keys present in both dicts.", ["Intersect the key sets."],
  "def common_keys(a, b):\n    return sorted(a.keys() & b.keys())", "Dict key views support set operations.", [({'a': 1, 'b': 2}, {'b': 3, 'c': 4}), ({}, {'a': 1})], [({'x': 1}, {'x': 2}), ({'p': 0}, {'q': 0}), ({'a': 1, 'b': 1, 'c': 1}, {'c': 1, 'a': 1})])
p("Dict difference", "M", "dicts", "dict_diff", "a, b", "Return a sorted list of keys whose values differ between `a` and `b`, including keys present in only one of them.", ["Iterate over the union of keys."],
  "def dict_diff(a, b):\n    keys = set(a) | set(b)\n    return sorted(k for k in keys if a.get(k, object()) != b.get(k, object()) or (k in a) != (k in b))", "Missing keys count as different.", [({'a': 1, 'b': 2}, {'a': 1, 'b': 3}), ({'a': 1}, {'a': 1, 'c': 2})], [({}, {}), ({'k': None}, {}), ({'x': 1}, {'x': 1.0, 'y': 2})])
p("Letter positions", "M", "dicts", "char_positions", "s", "Return a dict mapping each character to the list of indices where it occurs.", ["Append the index in a loop."],
  "def char_positions(s):\n    out = {}\n    for i, c in enumerate(s):\n        out.setdefault(c, []).append(i)\n    return out", "Group indices by character.", [("abca",), ("",)], [("aaa",), ("xyz",), ("banana",)])
p("Cache fibonacci", "M", "dicts", "fib_memo", "n", "Return the n-th Fibonacci number (`fib(0)=0`, `fib(1)=1`) using a dict for memoisation.", ["Store computed values and reuse them."],
  "def fib_memo(n):\n    memo = {0: 0, 1: 1}\n    def f(k):\n        if k not in memo:\n            memo[k] = f(k - 1) + f(k - 2)\n        return memo[k]\n    return f(n)", "Memoisation turns exponential recursion into linear.", [(10,), (1,)], [(0,), (2,), (30,), (50,)])
p("Duplicate words", "E", "counting", "duplicate_words", "text", "Return the sorted list of words (lowercased) that appear more than once in `text`.", ["Count lowercase words."],
  "def duplicate_words(text):\n    counts = {}\n    for w in text.lower().split():\n        counts[w] = counts.get(w, 0) + 1\n    return sorted(w for w, n in counts.items() if n > 1)", "Filter counts above one.", [("the cat and The dog and",), ("a b c",)], [("",), ("x x x",), ("A a B b c",)])
p("Winner of election", "M", "counting", "election_winner", "votes", "Given a list of candidate names, return the one with the most votes. Break ties alphabetically (smallest name wins).", ["Count, then `min` with a (-count, name) key."],
  "def election_winner(votes):\n    counts = {}\n    for v in votes:\n        counts[v] = counts.get(v, 0) + 1\n    return min(counts, key=lambda c: (-counts[c], c))", "The same pattern as most-frequent word.", [(['b', 'a', 'b'],), (['x'],)], [(['a', 'b'],), (['z', 'z', 'y', 'y'],), (['q', 'r', 'q'],)])
p("Sets: symmetric difference", "E", "sets", "symmetric_diff", "a, b", "Return the sorted list of values in exactly one of the two lists.", ["`^` on sets."],
  "def symmetric_diff(a, b):\n    return sorted(set(a) ^ set(b))", "XOR of sets.", [([1, 2, 3], [3, 4]), ([], [])], [([1], [1]), ([5, 6], []), ([1, 1, 2], [2, 3, 3])])
p("Is subset", "E", "sets", "is_subset", "a, b", "Return `True` if every element of list `a` appears in list `b`.", ["Compare sets."],
  "def is_subset(a, b):\n    return set(a) <= set(b)", "Subset operator.", [([1, 2], [1, 2, 3]), ([4], [1])], [([], []), ([], [1]), ([1, 1], [1])])
p("Unique elements in both counts", "M", "sets", "unique_in_one_only", "a, b", "Return the number of distinct values that occur in `a` but not in `b`, plus those in `b` but not in `a`.", ["Size of symmetric difference."],
  "def unique_in_one_only(a, b):\n    return len(set(a) ^ set(b))", "Counting after the set operation.", [([1, 2], [2, 3]), ([1], [1])], [([], [1, 2]), ([1, 2, 3], [4, 5, 6]), ([1, 1], [1])])
p("Happy number", "M", "sets", "is_happy", "n", "A number is happy if repeatedly replacing it by the sum of the squares of its digits reaches 1. Return whether `n >= 1` is happy.", ["Detect cycles with a set."],
  "def is_happy(n):\n    seen = set()\n    while n != 1 and n not in seen:\n        seen.add(n)\n        n = sum(int(c) ** 2 for c in str(n))\n    return n == 1", "Unhappy numbers enter a cycle.", [(19,), (2,)], [(1,), (7,), (4,), (100,), (20,)])
p("Jewels and stones", "E", "sets", "count_jewels", "jewels, stones", "`jewels` lists the characters that are jewels, `stones` the stones you have. Return how many stones are jewels (case-sensitive).", ["Put jewels in a set."],
  "def count_jewels(jewels, stones):\n    j = set(jewels)\n    return sum(1 for s in stones if s in j)", "Set membership is O(1).", [("aA", "aAAbbbb"), ("z", "ZZ")], [("", "abc"), ("abc", ""), ("ab", "abab")])
p("Distinct integers after reverse", "M", "sets", "distinct_with_reverses", "nums", "Add the reverse (digits reversed, e.g. 120 -> 21) of every number to the list, then return how many distinct values there are. Numbers are positive.", ["Reverse via string slicing and `int`."],
  "def distinct_with_reverses(nums):\n    vals = set(nums)\n    for x in nums:\n        vals.add(int(str(x)[::-1]))\n    return len(vals)", "A set handles duplicates created by reversing.", [([1, 13, 10, 12, 31],), ([2, 2, 2],)], [([120],), ([],), ([11, 22],)])
p("Tuple unpack min max", "E", "tuples", "min_max_pair", "nums", "Return `[min, max]` of a non-empty list in a single pass (no `min`/`max`).", ["Update two variables per element."],
  "def min_max_pair(nums):\n    lo = hi = nums[0]\n    for x in nums[1:]:\n        if x < lo:\n            lo = x\n        if x > hi:\n            hi = x\n    return [lo, hi]", "One pass tracks both.", [([3, 1, 4],), ([5],)], [([-2, -9],), ([2, 2],), ([1, 100, 50],)])
p("Sort pairs by second", "E", "tuples", "sort_pairs", "pairs", "Sort a list of `[a, b]` pairs by `b` ascending, breaking ties by `a` ascending.", ["Key `(p[1], p[0])`."],
  "def sort_pairs(pairs):\n    return sorted(pairs, key=lambda p: (p[1], p[0]))", "Tuple keys sort lexicographically.", [([[1, 3], [2, 1], [0, 3]],), ([],)], [([[5, 5]],), ([[2, 2], [1, 2]],), ([[1, 9], [3, 0], [2, 4]],)])
p("Closest pair of numbers", "M", "sorting", "min_abs_difference", "nums", "Return the smallest absolute difference between any two elements (at least two elements).", ["Sort, then check neighbours."],
  "def min_abs_difference(nums):\n    s = sorted(nums)\n    return min(b - a for a, b in zip(s, s[1:]))", "After sorting only neighbours matter.", [([4, 9, 1, 7],), ([5, 5],)], [([1, 2],), ([10, -10, 0],), ([100, 3, 50, 4],)])
p("Anagram mappings", "M", "dicts", "anagram_mapping", "a, b", "`b` is an anagram of list `a` (same multiset). Return a list `m` where `m[i]` is an index `j` in `b` with `b[j] == a[i]`, using each index of `b` once and always the smallest unused one.", ["Map each value to a queue of indices."],
  "def anagram_mapping(a, b):\n    pos = {}\n    for j, x in enumerate(b):\n        pos.setdefault(x, []).append(j)\n    used = {}\n    out = []\n    for x in a:\n        i = used.get(x, 0)\n        out.append(pos[x][i])\n        used[x] = i + 1\n    return out", "Consume indices left to right.", [([12, 28, 46, 32, 50], [50, 12, 32, 46, 28]), ([1, 1], [1, 1])], [([], []), ([5], [5]), ([1, 2, 1], [1, 1, 2])])
p("Count pairs with difference k", "M", "dicts", "count_pairs_diff", "nums, k", "Count index pairs `i < j` with `abs(nums[i] - nums[j]) == k` (`k > 0`).", ["Count previous occurrences of `x - k` and `x + k`."],
  "def count_pairs_diff(nums, k):\n    seen = {}\n    total = 0\n    for x in nums:\n        total += seen.get(x - k, 0) + seen.get(x + k, 0)\n        seen[x] = seen.get(x, 0) + 1\n    return total", "Each element pairs with earlier ones only.", [([1, 2, 2, 1], 1), ([1, 3], 3)], [([], 1), ([3, 2, 1, 5, 4], 2), ([1, 1, 1], 1)], lambda r: ([r.randint(1, 6) for _ in range(r.randint(2, 10))], r.randint(1, 3)))
p("Cache with limit", "H", "design", "lru_cache_ops", "capacity, ops", "Simulate an LRU cache of `capacity`. `ops` is a list: `['put', k, v]` stores a value (marking `k` most recent; evict the least recently used key if over capacity) and `['get', k]` returns the value or `-1` (a hit makes `k` most recent). Return the list of results of the `get` operations.", ["Keep an ordered structure; move a key to the end on access."],
  "def lru_cache_ops(capacity, ops):\n    from collections import OrderedDict\n    cache = OrderedDict()\n    out = []\n    for op in ops:\n        if op[0] == 'put':\n            _, k, v = op\n            if k in cache:\n                cache.move_to_end(k)\n            cache[k] = v\n            if len(cache) > capacity:\n                cache.popitem(last=False)\n        else:\n            k = op[1]\n            if k in cache:\n                cache.move_to_end(k)\n                out.append(cache[k])\n            else:\n                out.append(-1)\n    return out", "OrderedDict gives O(1) move and eviction.", [(2, [['put', 1, 1], ['put', 2, 2], ['get', 1], ['put', 3, 3], ['get', 2], ['get', 3]]), (1, [['put', 1, 1], ['put', 2, 2], ['get', 1]])], [(2, [['get', 5]]), (2, [['put', 1, 1], ['put', 1, 9], ['get', 1]]), (2, [['put', 1, 1], ['put', 2, 2], ['get', 1], ['put', 3, 3], ['get', 2], ['put', 4, 4], ['get', 1], ['get', 3], ['get', 4]])])
p("Time-based key value", "H", "design", "timemap_ops", "ops", "Simulate a time-based store. `['set', key, value, t]` records a value at time `t` (times for a key arrive increasing). `['get', key, t]` returns the value with the largest recorded time <= `t`, or `\"\"` if none. Return the results of the `get` operations.", ["Keep sorted (time, value) lists and binary search."],
  "def timemap_ops(ops):\n    import bisect\n    store = {}\n    out = []\n    for op in ops:\n        if op[0] == 'set':\n            _, k, v, t = op\n            store.setdefault(k, []).append((t, v))\n        else:\n            _, k, t = op\n            arr = store.get(k, [])\n            i = bisect.bisect_right(arr, (t, chr(0x10ffff)))\n            out.append(arr[i - 1][1] if i else '')\n    return out", "Binary search by time.", [([['set', 'a', 'x', 1], ['get', 'a', 1], ['get', 'a', 3], ['set', 'a', 'y', 4], ['get', 'a', 4], ['get', 'a', 5]],), ([['get', 'q', 1]],)], [([['set', 'k', 'v', 5], ['get', 'k', 4]],), ([['set', 'k', 'a', 1], ['set', 'k', 'b', 2], ['get', 'k', 2]],), ([['set', 'a', '1', 1], ['set', 'b', '2', 1], ['get', 'a', 9], ['get', 'b', 0]],)])
p("Randomised set simulation", "H", "design", "multiset_ops", "ops", "Simulate a multiset. `['add', x]` adds one copy, `['remove', x]` removes one copy if present and returns `True` else `False`, `['count', x]` returns the number of copies. Return the results of the `remove` and `count` operations in order.", ["A dict of counts."],
  "def multiset_ops(ops):\n    counts = {}\n    out = []\n    for op in ops:\n        name, x = op\n        if name == 'add':\n            counts[x] = counts.get(x, 0) + 1\n        elif name == 'remove':\n            if counts.get(x, 0) > 0:\n                counts[x] -= 1\n                out.append(True)\n            else:\n                out.append(False)\n        else:\n            out.append(counts.get(x, 0))\n    return out", "Each operation is O(1).", [([['add', 1], ['add', 1], ['count', 1], ['remove', 1], ['count', 1], ['remove', 2]],), ([['count', 5]],)], [([['remove', 1]],), ([['add', 'a'], ['remove', 'a'], ['remove', 'a'], ['count', 'a']],), ([['add', 2], ['add', 3], ['count', 2], ['count', 3]],)])
p("Min stack ops", "M", "design", "min_stack_ops", "ops", "Simulate a stack supporting `['push', x]`, `['pop']`, `['top']` and `['min']` (the minimum currently in the stack). Return the results of `top` and `min` operations in order. Pops and queries only happen on non-empty stacks.", ["Store the running minimum next to each element."],
  "def min_stack_ops(ops):\n    stack = []\n    out = []\n    for op in ops:\n        if op[0] == 'push':\n            x = op[1]\n            stack.append((x, min(x, stack[-1][1]) if stack else x))\n        elif op[0] == 'pop':\n            stack.pop()\n        elif op[0] == 'top':\n            out.append(stack[-1][0])\n        else:\n            out.append(stack[-1][1])\n    return out", "Pairs make min O(1).", [([['push', 3], ['push', 1], ['min'], ['pop'], ['min'], ['top']],), ([['push', 5], ['top']],)], [([['push', 2], ['push', 2], ['pop'], ['min']],), ([['push', -1], ['push', 4], ['min'], ['top']],), ([['push', 9], ['push', 8], ['push', 7], ['pop'], ['min']],)])
p("Queue via two stacks", "M", "design", "queue_ops", "ops", "Simulate a FIFO queue with `['enqueue', x]` and `['dequeue']`. Return the list of values returned by dequeues (dequeues only happen on non-empty queues).", ["Two stacks: input and output."],
  "def queue_ops(ops):\n    inbox, outbox, out = [], [], []\n    for op in ops:\n        if op[0] == 'enqueue':\n            inbox.append(op[1])\n        else:\n            if not outbox:\n                while inbox:\n                    outbox.append(inbox.pop())\n            out.append(outbox.pop())\n    return out", "Move items only when the output stack is empty.", [([['enqueue', 1], ['enqueue', 2], ['dequeue'], ['enqueue', 3], ['dequeue'], ['dequeue']],), ([['enqueue', 7], ['dequeue']],)], [([],), ([['enqueue', 'a'], ['enqueue', 'b'], ['dequeue']],), ([['enqueue', 1], ['dequeue'], ['enqueue', 2], ['dequeue']],)])
